UPDATE products SET presentation = json_set(presentation, '$.bundleMode', json('true')), revision = revision + 1 WHERE json_type(presentation, '$.bundleMode') IS NULL AND json_array_length(offers) BETWEEN 1 AND 2 AND NOT EXISTS (SELECT 1 FROM json_each(products.offers) WHERE json_extract(value, '$.quantity') < 2) AND EXISTS ( SELECT 1 FROM json_each(products.offers) WHERE COALESCE(json_extract(value, '$.enabled'), 1) = 1 AND (json_extract(value, '$.endsAt') IS NULL OR json_extract(value, '$.endsAt') > strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) );
